import { exec } from "node:child_process";
import { chmodSync, existsSync, mkdirSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { promisify } from "node:util";

const execAsync = promisify(exec);

/**
 * Generates the Linux/macOS shell script wrapper.
 */
function generateUnixShim(appExePath) {
  return `#!/usr/bin/env bash
# QuotaLens & AI Limits CLI Launcher
# Generated by QuotaLens Desktop

TARGET_EXE="${appExePath}"

if [ ! -f "$TARGET_EXE" ]; then
  # Fallback locations
  for candidate in \\
    "/Applications/QuotaLens.app/Contents/MacOS/QuotaLens" \\
    "$HOME/Applications/QuotaLens.app/Contents/MacOS/QuotaLens" \\
    "/opt/QuotaLens/quotalens" \\
    "/usr/bin/quotalens"
  do
    if [ -x "$candidate" ]; then
      TARGET_EXE="$candidate"
      break
    fi
  done
fi

if [ ! -f "$TARGET_EXE" ]; then
  echo "QuotaLens CLI Error: Application binary not found at $TARGET_EXE" >&2
  exit 1
fi

# On macOS, check inside app bundle for app.asar
if [ "$(uname -s)" = "Darwin" ]; then
  ASAR_PATH="$(dirname "$TARGET_EXE")/../Resources/app.asar"
  if [ -f "$ASAR_PATH" ]; then
    export ELECTRON_RUN_AS_NODE=1
    exec "$TARGET_EXE" "$ASAR_PATH/dist/cli/index.js" "$@"
  fi
fi

# On Linux unpackaged or deb package, check resources/app.asar
APP_DIR="$(dirname "$TARGET_EXE")"
if [ -f "$APP_DIR/resources/app.asar" ]; then
  export ELECTRON_RUN_AS_NODE=1
  exec "$TARGET_EXE" "$APP_DIR/resources/app.asar/dist/cli/index.js" "$@"
fi

# Fallback: pass directly to app with --no-sandbox
exec "$TARGET_EXE" --no-sandbox "$@"
`;
}

/**
 * Generates the Windows CMD batch wrapper.
 */
function generateWindowsCmd(appExePath) {
  return `@echo off
setlocal
set "ELECTRON_RUN_AS_NODE=1"
set "APP_EXE=${appExePath}"

if exist "%~dp0QuotaLens.exe" (
  set "APP_EXE=%~dp0QuotaLens.exe"
)

for %%I in ("%APP_EXE%") do set "APP_DIR=%%~dpI"

if exist "%APP_DIR%resources\\app.asar" (
  "%APP_EXE%" "%APP_DIR%resources\\app.asar\\dist\\cli\\index.js" %*
) else if exist "%~dp0resources\\app.asar" (
  "%APP_EXE%" "%~dp0resources\\app.asar\\dist\\cli\\index.js" %*
) else (
  "%APP_EXE%" %*
)
endlocal
`;
}

/**
 * Generates the Windows Bash wrapper for Git Bash / MSYS2 users.
 */
function generateWindowsBash(appExePath) {
  return `#!/usr/bin/env bash
# QuotaLens CLI Launcher for Git Bash / Windows
export ELECTRON_RUN_AS_NODE=1
APP_EXE="${appExePath.replace(/\\/g, "/")}"
APP_DIR="$(dirname "$APP_EXE")"

if [ -f "$APP_DIR/resources/app.asar" ]; then
  exec "$APP_EXE" "$APP_DIR/resources/app.asar/dist/cli/index.js" "$@"
else
  exec "$APP_EXE" "$@"
fi
`;
}

/**
 * Installs CLI shims for QuotaLens and ai-limits into the user's environment.
 */
export async function installCliIntegration(_options = {}) {
  const isWin = process.platform === "win32";
  const isMac = process.platform === "darwin";
  const installedPaths = [];

  // Determine current executable path
  let appExe = process.execPath;
  if (process.env.APPIMAGE) {
    appExe = process.env.APPIMAGE;
  } else if (isMac && !appExe.startsWith("/Applications/")) {
    if (existsSync("/Applications/QuotaLens.app/Contents/MacOS/QuotaLens")) {
      appExe = "/Applications/QuotaLens.app/Contents/MacOS/QuotaLens";
    }
  }

  try {
    if (isWin) {
      // 1. Install CMD and Bash shims into %LOCALAPPDATA%\QuotaLens\bin
      const localAppData = process.env.LOCALAPPDATA || join(homedir(), "AppData", "Local");
      const binDir = join(localAppData, "QuotaLens", "bin");
      mkdirSync(binDir, { recursive: true });

      const cmdContent = generateWindowsCmd(appExe);
      const bashContent = generateWindowsBash(appExe);

      for (const name of ["quotalens", "ai-limits"]) {
        const cmdPath = join(binDir, `${name}.cmd`);
        const bashPath = join(binDir, name);
        writeFileSync(cmdPath, cmdContent, "utf8");
        writeFileSync(bashPath, bashContent, "utf8");
        installedPaths.push(cmdPath);
      }

      // Also place .cmd files directly in the app directory alongside QuotaLens.exe if writable
      const appDir = dirname(process.execPath);
      try {
        writeFileSync(join(appDir, "quotalens.cmd"), cmdContent, "utf8");
        writeFileSync(join(appDir, "ai-limits.cmd"), cmdContent, "utf8");
      } catch {
        // App dir might be read-only if installed to Program Files
      }

      // Update User PATH via PowerShell if not present
      try {
        const psCommand = `powershell -NoProfile -NonInteractive -Command "$d='${binDir.replace(/'/g, "''")}'; $p=[Environment]::GetEnvironmentVariable('PATH','User'); if($p -notlike ('*'+$d+'*')){ [Environment]::SetEnvironmentVariable('PATH', ($p+';'+$d), 'User') }"`;
        await execAsync(psCommand);
      } catch {
        // Silently continue if PowerShell PATH update fails
      }
    } else {
      // Linux or macOS
      const userBin = join(homedir(), ".local", "bin");
      mkdirSync(userBin, { recursive: true });

      const shimContent = generateUnixShim(appExe);

      for (const name of ["quotalens", "ai-limits"]) {
        const shimPath = join(userBin, name);
        // If symlink exists, unlink it first so writeFileSync doesn't write through a broken target
        try {
          const lstat = await import("node:fs").then((f) => f.lstatSync(shimPath));
          if (lstat.isSymbolicLink()) {
            await import("node:fs").then((f) => f.unlinkSync(shimPath));
          }
        } catch {
          // File does not exist, ignore
        }
        writeFileSync(shimPath, shimContent, { encoding: "utf8", mode: 0o755 });
        try {
          chmodSync(shimPath, 0o755);
        } catch {
          // Ignore
        }
        installedPaths.push(shimPath);
      }

      // On macOS or root, try /usr/local/bin if writable
      const sysBin = "/usr/local/bin";
      if (existsSync(sysBin)) {
        try {
          for (const name of ["quotalens", "ai-limits"]) {
            const sysPath = join(sysBin, name);
            try {
              const lstat = await import("node:fs").then((f) => f.lstatSync(sysPath));
              if (lstat.isSymbolicLink()) {
                await import("node:fs").then((f) => f.unlinkSync(sysPath));
              }
            } catch {
              // Ignore
            }
            writeFileSync(sysPath, shimContent, {
              encoding: "utf8",
              mode: 0o755,
            });
            try {
              chmodSync(sysPath, 0o755);
            } catch {
              // Ignore
            }
            installedPaths.push(sysPath);
          }
        } catch {
          // Expected to fail if not root or admin; userBin covers it
        }
      }

      // Check if ~/.local/bin is in PATH; if not, suggest or add to shell rc
      const pathEnv = process.env.PATH || "";
      if (!pathEnv.includes(".local/bin")) {
        try {
          const bashrc = join(homedir(), ".bashrc");
          const zshrc = join(homedir(), ".zshrc");
          const line = '\nexport PATH="$HOME/.local/bin:$PATH"\n';
          if (existsSync(bashrc)) {
            const content = await import("node:fs").then((f) => f.readFileSync(bashrc, "utf8"));
            if (!content.includes(".local/bin")) {
              await import("node:fs").then((f) => f.appendFileSync(bashrc, line));
            }
          }
          if (existsSync(zshrc)) {
            const content = await import("node:fs").then((f) => f.readFileSync(zshrc, "utf8"));
            if (!content.includes(".local/bin")) {
              await import("node:fs").then((f) => f.appendFileSync(zshrc, line));
            }
          }
        } catch {
          // Ignore
        }
      }
    }

    return {
      success: true,
      paths: installedPaths,
      message: `QuotaLens CLI commands ('quotalens' and 'ai-limits') installed successfully to:\n${installedPaths.join("\n")}`,
    };
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : String(err);
    return {
      success: false,
      paths: installedPaths,
      message: `Failed to install CLI integration: ${errorMsg}`,
    };
  }
}
